  // ABS covers HOME directories and Windows drive letters. It does NOT cover the machine's
  // TEMP roots, and an agent's scratch directory is where a drive's intermediate work
  // actually lives: two committed records carry `/tmp/vlm.md` and a `/private/tmp/.../scratchpad`
  // path that ABS let straight through. Same whole-line drop, three more anchored shapes.
  //
  // THE BACKSTOP FOLLOWS THIS, FORWARD ONLY (owner ratification 2026-08-16 — Q2 of
  // `.claude/veriloop/specs/review-remediation-2026-08-15.md`, which this drop shipped ahead
  // of, emit-time only, while the question was open). `lint-bundle.mjs`'s committed-record
  // scan now applies the SAME three shapes to any record whose FILENAME timestamp parses to
  // 2026-08-16T00:00:00Z or later; records before the cutoff — the two already committed
  // here — are still scanned with ABS alone, because widening it retroactively would turn the
  // gate red on history nobody can rewrite without the owner. This routine is unchanged by
  // that ruling: it has dropped these lines since 2026-08-15 and still does.
  //
  // The shapes are ANCHORED, and both halves of the anchor are load-bearing:
  //   - a leading `^` or a NON-WORD character, so `docs/private/notes.md` — a repo-relative
  //     path with `private` as a plain directory name — is NOT a temp path. The class
  //     deliberately does NOT exclude `/`: excluding it left `file:///tmp/x` and any
  //     double-slashed `…//tmp/…` through, since the character before `/tmp/` is itself a
  //     slash there. A word character before the slash is what marks a relative path;
  //     another slash marks nothing;
  //   - a negative lookbehind on `%REPO%`, because `stripRoots` runs FIRST and rewrites every
  //     in-root path to `%REPO%/…`. Without it a repo that simply has a `tmp/` directory would
  //     have every line mentioning `%REPO%/tmp/x` dropped from its own attestation. The
  //     lookbehind, not the anchor class, is what protects that case — widening the class
  //     does not weaken it.
  const TEMP = /(?:^|[^\w])(?<!%REPO%)\/(?:private|tmp|var\/folders)\//;
  const rootList = (roots || [])
    .filter((r) => typeof r === 'string' && r.length)
    .sort((a, b) => b.length - a.length); // longest-first: a worktree prefix before its parent
  const stripRoots = (s) => {
    let out = String(s);
    for (const r of rootList) out = out.split(r).join('%REPO%');
    return out;
  };
  // strip known roots, then drop any line STILL carrying an absolute path, a temp-root path
  // or a secret-shaped pattern (the safety net) — whole-line drop only, never partial masking.
  // PEM private-key blocks get a RANGE drop: every line from a PEM_BEGIN match through the
  // matching PEM_END (inclusive) is dropped, including the base64 body in between, which
  // matches no single-line SECRET_PATTERNS entry on its own. If PEM_END never appears, the
  // block drop runs to the end of the field rather than leaking an unterminated key.
  const redactStr = (s) => {
    const out = [];
    let inPemBlock = false;
    for (const line of stripRoots(s).split('\n')) {
      if (inPemBlock) {
        if (PEM_END.test(line)) inPemBlock = false;
        continue; // every line inside the block, and the END line itself, is dropped
      }
      if (PEM_BEGIN.test(line)) { inPemBlock = true; continue; }
      if (!ABS.test(line) && !TEMP.test(line) && !SECRET_PATTERNS.some((re) => re.test(line))) out.push(line);
    }
    return out.join('\n');
  };
  const redact = (v) => {
    if (v == null || typeof v === 'number' || typeof v === 'boolean') return v;
    if (typeof v === 'string') return redactStr(v);
    if (Array.isArray(v)) {
      // redact each entry, then drop string entries that redaction emptied (a single-line
      // path that still matched the ABS regex collapses to '') so no bare path survives.
      return v.map(redact).filter((e) => !(typeof e === 'string' && e.length === 0));
    }
    const o = {};
    for (const k of Object.keys(v)) o[k] = redact(v[k]);
    return o;
  };
  // screenshot paths normalize to repo-relative first; the recursive net drops any that
  // could not be rooted (still absolute) rather than leaking them.
  const shot = evidence.screenshot || null;
  const normShot = (p) => stripRoots(p).replace(/^%REPO%[\\/]+/, '');
  const screenshots = shot && Array.isArray(shot.captured) ? shot.captured.map(normShot) : [];
  const land = evidence.land
    ? { sha: evidence.land.commitSha || null, pushed: !!evidence.land.pushed, branch: evidence.land.branch || (ctx && ctx.branch) || null }
    : null;
